-- Carga oficial fornecida para a semana 037/2026 (914 confirmações SAP).
DO $seed$
DECLARE
  target_week_id uuid;
  target_worksite_id uuid;
  new_import_id uuid;
BEGIN
  SELECT w.id, w.worksite_id INTO target_week_id, target_worksite_id
  FROM public.weeks w
  JOIN public.worksites s ON s.id = w.worksite_id
  WHERE s.code = 'RPBC'
    AND w.start_date = DATE '2026-09-07'
    AND w.end_date = DATE '2026-09-11'
  ORDER BY w.created_at DESC
  LIMIT 1;

  IF target_week_id IS NULL THEN
    RAISE NOTICE 'Semana 037/2026 da RPBC ainda não existe; carga SAP oficial não aplicada.';
    RETURN;
  END IF;

  DELETE FROM public.sap_confirmation_imports
  WHERE week_id = target_week_id AND source_label = 'Carga oficial semana 37';

  INSERT INTO public.sap_confirmation_imports (worksite_id, week_id, source_file_name, source_label, row_count)
  VALUES (target_worksite_id, target_week_id, 'Extracao SAP semana 37.txt', 'Carga oficial semana 37', 914)
  RETURNING id INTO new_import_id;

